// Sends msg.payload messages, numbered 1, 2, 3... The number keeps
// counting across clicks, so the order is easy to check later.
const count = Math.max(1, Math.min(10000, Number(msg.payload) || 1));
let n = context.get('n') || 0;
for (let i = 0; i < count; i++) {
    n += 1;
    node.send({ payload: { n: n, createdAt: new Date().toISOString() } });
}
context.set('n', n);
return null;
